{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Apply exponential recency weighting to valid next-item losses across all four datasets, retaining the existing detached negative-score weighting. Normalize recency weights to mean one over valid targets. This emphasizes recent transitions without changing the GRU, sampling, optimizer, schedule, or inference.",
      "edits": [
        {
          "find": "    valid_pos = pos_scores[mask]\n    valid_neg = neg_scores[mask]\n    weights = torch.softmax(valid_neg.detach(), dim=0)\n    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)\n    return (weights * pairwise_loss).sum()",
          "replace": "    valid_pos = pos_scores[mask]\n    valid_neg = neg_scores[mask]\n    weights = torch.softmax(valid_neg.detach(), dim=0)\n    positions = torch.arange(pos.size(1), device=pos.device).unsqueeze(0).expand_as(pos)\n    latest = positions.masked_fill(~mask, -1).max(dim=1, keepdim=True).values\n    distances = (latest - positions).clamp_min(0)\n    recency_weights = torch.exp(-distances[mask].to(valid_pos.dtype) / 20.0)\n    recency_weights = recency_weights / recency_weights.mean()\n    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)\n    return (weights * recency_weights * pairwise_loss).sum()"
        }
      ]
    }
  ],
  "change_summary": "Add mean-normalized exp(-distance/20) temporal loss weighting to the shared training objective. Prediction and checkpoint formats remain unchanged."
}
